const sketch = (p:any) => {
    p.setup = () => {
p.createCanvas(500, 500);      // Window Size
p.colorMode(p.RGB, 1.0); // RGB(0.0~1.0)
var fR, fG, fB;      // Window RGB
for (var iX=0; iX<p.width; iX++)
{
  for (var iY=0; iY<p.height; iY++)
  {
    /* Example */
    fR = p.cos((iX/50.0)*p.sin(iY/130.0)-p.tan(iX/4.0));
    fG = p.sin((iX/55.0)*p.sin(iY/80.0)-p.tan(iX/4.0));
    fB = (p.pow(iX-130, 2.5)+p.pow(iY+200, 1.8))/(10.0*iY*iX);

    // draw pixel
    p.stroke(fR, fG, fB);
    p.point(iX, iY);
  }
}

  };
};

export default sketch;
