const sketch = (p5obj:any) => {
p5obj.setup = () => 
{
  p5obj.createCanvas( 1000, 1000 );
  p5obj.background(0, 97, 146);
  for (let i: number = 0; i<1001; i++)
  {
    p5obj.stroke(0, 200-i/20, 200+i/20);
    p5obj.line(0, i+100, p5obj.width, i+100);
  }
  kaigan();    //海岸線

  island(80, 500, 300, 3);
  island(320, 400, 200, 3);
  island(510, 300, 300, 3);
  island(680, 400, 300, 3);
  island(880, 500, 200, 3);
}

const kaigan = () => {
  p5obj.fill(50, 200, 140);
  p5obj.strokeWeight(10);
  p5obj.stroke(230, 230, 160);
  p5obj.strokeJoin(p5obj.ROUND);
  p5obj.beginShape();    //リアス式海岸
  p5obj.vertex(-50, -50);
  for (let iX: number = 0; iX <1200; iX += 30)
  {
    p5obj.vertex(iX, p5obj.random((iX-500)/30*(iX-500)/30+250, (iX-500)/30*(iX-500)/30+300));
  }
  p5obj.vertex(1000, -50);
  p5obj.endShape(p5obj.CLOSE);
  for (let i: number = 0; i<200; i++)
  {
    p5obj.strokeWeight(1);
    p5obj.stroke(i/4, 100+i/2, 100+i/5);
    p5obj.line(0, i, p5obj.width, i);
  }
}

const island = (sX: number, sY: number, iSize: number, iLevel: number) => {
  p5obj.fill(50, 200, 140);
  p5obj.strokeWeight(3+iLevel);
  p5obj.stroke(230, 230, 160);
  p5obj.strokeJoin(p5obj.ROUND);
  p5obj.beginShape();
  let lilisland: number = iSize/3;
  p5obj.vertex(sX+lilisland/4, sY+lilisland/4);
  p5obj.vertex(p5obj.random(sX+lilisland/3, sX+lilisland), p5obj.random(sY, sY+lilisland/4));
  p5obj.vertex(sX+lilisland, p5obj.random(sY+lilisland/3, sY+lilisland));
  p5obj.vertex(p5obj.random(sX+lilisland/3, sX+lilisland), sY+lilisland);
  p5obj.vertex(p5obj.random(sX, sX+lilisland/4), sY+lilisland);
  p5obj.vertex(sX, p5obj.random(sY, sY+lilisland));
  p5obj.vertex(sX+lilisland/4, sY+lilisland/4);
  p5obj.endShape(p5obj.CLOSE);

  if (iLevel>1)
  {
    island(p5obj.random(sX-sX/4, sX), p5obj.random(sY+iSize/3, sY+5*iSize/4), iSize/2, iLevel-1);
    island(p5obj.random(sX+iSize/4, sX+iSize/2), p5obj.random(sY+iSize/3, sY+5*iSize/4), iSize/2, iLevel-1);
  }
}

};

export default sketch;
