const sketch = (p5obj:any) => {
    p5obj.setup = () => {
p5obj.createCanvas(500, 500);
p5obj.background('#f39800');

// random clock
for (var i = 25; i < 500; i += 50) { // row
  for (var j = 25; j < 500; j += 50) { // column
    p5obj.strokeWeight(4);
    p5obj.stroke(p5obj.random(0, 100), p5obj.random(0, 100), p5obj.random(0, 100));
    p5obj.ellipse( i, j, 40, 40);
    p5obj.line(i, j, i + p5obj.random(-8, 8), j + p5obj.random(-12, 12));
    p5obj.line(i, j, i + p5obj.random(-8, 8), j + p5obj.random(-12, 12));
  }
}

  };
};

export default sketch;
