const sketch = (p5obj:any) => {
    p5obj.setup = () => {
p5obj.createCanvas(500, 500);
p5obj.background(2, 40, 89); /* '#022859', 豼・ｴｺ */
p5obj.noStroke();
p5obj.ellipseMode(p5obj.CENTER);
p5obj.rectMode(p5obj.CENTER);

/* 4遞ｮ縺ｮ陞ｺ譌区峇邱壹ｒ驥阪・蜷医ｏ縺帙∫せ繧・縺､謠冗判縺吶ｋ縺溘・縺ｫ蜴溽せ蜻ｨ繧翫・蝗櫁ｻ｢繧呈命縺・ */

p5obj.blendMode(p5obj.ADD); /* 蜉邂玲婿蠑上↓繧医ｋ豺ｷ濶ｲ */
p5obj.translate(p5obj.width/2, p5obj.height/2);
var theta = 0;

for (var i=0; i<2000; i++) {

  p5obj.rotate(p5obj.PI/16);
  p5obj.fill(2, 40, 89, 45); /* '#022859', 閭梧勹縺ｨ蜷瑚牡縲∬埋縺・*/
  p5obj.square(p5obj.pow(theta, 2)*p5obj.cos(theta), p5obj.pow(theta, 2)*p5obj.sin(theta), 10);

  p5obj.rotate(p5obj.PI/5);
  p5obj.fill(217, 39, 39, 125); /* '#d92727', 譛ｱ濶ｲ縲∝濠騾乗・ */
  p5obj.square(p5obj.pow(theta, 2)*p5obj.cos(theta), p5obj.pow(theta, 2)*p5obj.sin(theta), 5);

  p5obj.rotate(p5obj.PI/7);
  p5obj.fill(242, 25, 75, 25); /* '#f2194b', 邏・牡縲∬埋縺・*/
  p5obj.square(p5obj.pow(theta, 2)*p5obj.cos(theta), p5obj.pow(theta, 2)*p5obj.sin(theta), 20);

  p5obj.rotate(p5obj.PI/3);
  p5obj.fill(124, 108, 46, 175); /* '#7c6c2e', 鮟・悄濶ｲ縲∝濠騾乗・ */
  p5obj.circle(p5obj.pow(theta, 5)*p5obj.cos(theta)/5, p5obj.pow(theta, 5)*p5obj.sin(theta)/5, 5);

  theta += 0.01;
}

  };
};

export default sketch;
