const sketch = (p5obj:any) => {
p5obj.setup = () => 
{
  p5obj.createCanvas(1000, 1000);
  p5obj.colorMode(p5obj.RGB, 255);
  p5obj.background(p5obj.random(80), p5obj.random(10), p5obj.random(60));//背景
  p5obj.blendMode( p5obj.SCREEN );
  p5obj.stroke(p5obj.random(255), p5obj.random(180), 200, 230);//色相
  p5obj.noFill();
  p5obj.translate(p5obj.width/2, p5obj.height/2);//座標
  Hana(0, 0, 400, 160, 5, 10);

  for (let g: number = 40; g<=500; g++)
  {

    p5obj.strokeWeight(0.7);
    p5obj.beginShape();
    p5obj.vertex(p5obj.random(40), 40);
    p5obj.vertex(70, 50);
    p5obj.vertex(15, 85);
    p5obj.vertex(p5obj.random(120), 85);
    p5obj.vertex(55, 115);
    p5obj.vertex(85, p5obj.random(120));
    p5obj.endShape(p5obj.CLOSE);//頭花
    p5obj.rotate(p5obj.radians(60));
  }
  
  p5obj.save("sk_k4_22_D13.png");
}

const Hana = (fX: number, fY: number, fsize: number, fWidth: number, fHeight: number, i: number) => {

  let fEndX: number = fX+fsize*p5obj.cos(p5obj.radians(fWidth)) ;
  let fEndY: number = fY+fsize*p5obj.sin(p5obj.radians(fWidth)) ;//終点座標

  p5obj.strokeWeight(2);
  p5obj.bezier( 200, 300, fX/2, fY/2, p5obj.random(fWidth/2, i*5)-fX, p5obj.random(fHeight/2, i/5)-fY, fsize+300, fsize+300); //花弁
  p5obj.rotate(p5obj.radians(80));

  p5obj.ellipse(fX, fY, p5obj.width/80, p5obj.height/80);//花粉

  if (fsize>5)
  {
    Hana( fEndX, fEndY, fsize/2, fWidth*p5obj.random(2.0), fHeight+20, i-1);
    Hana( fEndX, fEndY, fsize/2, fWidth*p5obj.random(2.0), fHeight-30, i+1);
  }
}

};

export default sketch;
