const sketch = (p5obj:any) => {
/**
ブルーベリーの木をモチーフに、再帰的な表現を試みた.
授業の演習にもあったように植物の構造は繰り返しでできているため、
そこから更に発展して枝のほかに実と葉を再現しようと思った。
再帰した際、ブルーベリーがただの紫色の円に見えないように実の中央に蔕を描画した。
低木特有の、塊に近い形状を再現するために密度を下方に集中させ、
主幹ができる限り目立たないようにした。
*/
p5obj.setup = () => 
{
  p5obj.createCanvas( 1000, 1000);
  p5obj.noLoop();
}

p5obj.draw = () => 
{
  p5obj.background(220, 220, 230);
  p5obj.strokeWeight(10);

  for ( let i: number = -300; i<=400; i+=80 )
  {
    p5obj.push();
    p5obj.translate( p5obj.width/2, 1150);
    branch(0);
    p5obj.pop();
  }
  p5obj.save("sk_k4_22_B09.png");
}

//枝と茎
const branch = (stem: number) => {
  if ( stem < 9 )
  {
    p5obj.stroke( 70, 64, 50 );
    p5obj.line( 3, 3, 2, -p5obj.height/5 );
    {
      p5obj.translate( 0, -p5obj.height/12 );
      p5obj.rotate( p5obj.random( -0.1, 0.1 ) );
      
      if( p5obj.random(2.3)<1.1 )
      {
        p5obj.rotate( 0.3 );
        p5obj.scale( 0.72 );
        p5obj.push();
        branch( stem+1 );
        p5obj.pop();
        p5obj.rotate( -0.7 );
        p5obj.push();
        branch( stem+1);
        p5obj.pop();
      }
      else
      {
        branch( stem );
      }
    }
  }
  else
  {
    //葉
    p5obj.stroke(75, 100, 40);
    p5obj.fill(70, 140, 65);
    p5obj.ellipse(100, 500, p5obj.random(500, 100), p5obj.random(170, 50));

    //ブルーベリー1​
    p5obj.noStroke();
    p5obj.fill( 100, 0, 220 );
    p5obj.ellipse( 0, 0, p5obj.random(120, 100), p5obj.random(100, 100) );
    p5obj.stroke(0);
    
    //ブルーベリー2​
    p5obj.noStroke();
    p5obj.fill( 130, 0, 220 );
    p5obj.ellipse( 70, 30, p5obj.random(100, 100), p5obj.random(100, 100) );
    p5obj.stroke(0);
    
    //ブルーベリーの蔕1​
    p5obj.fill(10, 100, 220);
    p5obj.ellipse( 0, 0, p5obj.random(10, 10), p5obj.random(10, 10) );
    
    //ブルーベリーの蔕2​
    p5obj.fill(10, 100, 220);
    p5obj.ellipse( 70, 30, p5obj.random(10, 10), p5obj.random(10, 10) ); 
  }
}

//マウスクリックで描画​
const mousePressed = () => {
  p5obj.redraw();
}

};

export default sketch;
