const sketch = (p5obj:any) => {
p5obj.setup = () => 
{
  p5obj.createCanvas( 1000, 1000 );//サイズ指定

  p5obj.noLoop();
  
  // 描画処理実行中テキスト
  p5obj.textSize(40);
  p5obj.fill(0);
  p5obj.text("Now Genegating Image......Please Wait", 100, 500);
}

p5obj.draw = () => 
{
  //背景のグラデーション
  for (let g: number = 0; g<=1000; g++)
  {
    p5obj.noFill();
    p5obj.stroke(215-g*0.2, 255-g*0.1, 250);//空の色
    p5obj.rect(0, 0, g, g);
  }
 
  p5obj.noStroke();//左上の太陽
  p5obj.fill(255);
  p5obj.circle(0, 0, 70);


  p5obj.fill(20, 150, 188);//海色
  p5obj.rect(0, 600, p5obj.width, 300);//背景の海

  star(p5obj.width, p5obj.height, 100);//ほんわか描画
  
  // 紅葉山の連続描画
  for ( let irock: number = 0; irock < 30; irock++ )
  {
    drawmountain( p5obj.random(p5obj.width), p5obj.random( 800, 1000), p5obj.random( p5obj.width), p5obj.random( 800, 1000), 7);
  }

  drawtree(p5obj.width, p5obj.height, p5obj.random(60, 150), -90, 20);//手前の木々の出現座標
  drawtree(-50, p5obj.height-p5obj.random(300), p5obj.random(100, 250), -90, 20);
  drawtree(p5obj.width/2, p5obj.height+350, p5obj.random(50, 150), -90, 20);
}

//森山を生成
const drawmountain = (fBeginX: number, fBeginY: number, fEndX: number, fEndY: number, count: number) => { 
  // 開始点から終了点への距離
  let fLength: number = p5obj.sqrt( p5obj.pow( fEndX - fBeginX, 2) + p5obj.pow( fEndY - fBeginY, 2 ) );

  if ( fLength > 3 )
  {
    // 直角三角形のX軸方向の大きさ
    let fTriangleX: number = ( fEndX - fBeginX ) / 2;

    // 直角三角形のY軸方向の大きさ
    let fTriangleY: number = ( fBeginY - fEndY ) /2;  

    let fBeginToNewX: number = fTriangleX + fTriangleY;
    let fEndToNewY: number = fTriangleX + fTriangleY;

    // 新たに生成される点のXY座標値
    let fNewX: number = fBeginX + fBeginToNewX;
    let fNewY: number = fEndY + fEndToNewY;

    // 二つの線に再帰的に分割
    drawmountain( fBeginX, fBeginY, fNewX, fNewY, count );
    drawmountain( fEndX, fEndY, fNewX, fNewY, count );
  } else
  {
    p5obj.colorMode(p5obj.HSB);//カラーモードをHSBに

    p5obj.strokeWeight(2);//山の霧か雲
    p5obj.stroke(40, 30, 280, p5obj.random(80));
    p5obj.line( fBeginX, fBeginY, fEndX, fEndY);

    p5obj.strokeWeight(4);//紅葉
    p5obj.stroke(p5obj.random(-10, 30), 190, p5obj.random(170, 280));
    p5obj.line( fBeginX-100, fBeginY+65, fEndX-100, fEndY+60 );

    p5obj.strokeWeight(3);//黄色い葉っぱ
    p5obj.stroke(p5obj.random(30, 50), 240, p5obj.random(180, 280));
    p5obj.line( fBeginX, fBeginY+240, fEndX+5, fEndY+240 );

    p5obj.strokeWeight(2);//山影
    p5obj.stroke(150, 200, p5obj.random(50, 150), p5obj.random(200));
    p5obj.line( fBeginX-90, fBeginY+220, fEndX-90, fEndY+180 );

    p5obj.strokeWeight(1.4);//紅葉枝
    p5obj.stroke(p5obj.random(30, 40), 150, p5obj.random(20, 250));
    p5obj.line( fBeginX-100, fBeginY+70, fEndX-100, fEndY+80 );

    p5obj.strokeWeight(2.4);//針葉樹
    p5obj.stroke(p5obj.random(40, 65), 140, p5obj.random(30, 230));
    p5obj.line( fBeginX-100, fBeginY+120, fEndX-100, fEndY+130 );

    p5obj.strokeWeight(1.4);//滝
    p5obj.stroke(105, 70, p5obj.random(70, 280));
    p5obj.line( fBeginX-200, fBeginY+370, fEndX-200, fEndY+440 );
  }
}

//手前の木々を生成
const drawtree = (fBeginX: number, fBeginY: number, fLength: number, fDegree: number, iLevel: number) => {

  let fEndX: number = fBeginX + fLength * p5obj.cos( p5obj.radians( fDegree ) );
  let fEndY: number = fBeginY + fLength * p5obj.sin( p5obj.radians( fDegree ) );

  p5obj.line( fBeginX, fBeginY, fEndX, fEndY );
  if (iLevel>1)
  {
    p5obj.stroke(p5obj.random(5, 35), 220, p5obj.random(245, 320));
    p5obj.strokeWeight(p5obj.random(1.4, 4.5));
    drawtree( fEndX, fEndY, fLength *p5obj.random( 0.6, 0.9), fDegree + p5obj.random(40), iLevel - 1 );//紅葉１
    drawtree( fEndX, fEndY, fLength * p5obj.random(0.5, 0.9), fDegree -p5obj.random( 30), iLevel - 1 );//紅葉２


    p5obj.strokeWeight(p5obj.random(3, 8));
    p5obj.stroke(p5obj.random(120, 150), 170, p5obj.random(60, 120));
    drawtree( fEndX+10, fEndY+15, fLength * p5obj.random(0.55, 0.7), fDegree +p5obj.random( 30), iLevel -2);//木の陰
  }
}

//空の丸いほんわかを生成
const star = (iX: number, iY: number, iLevel: number) => {
  p5obj.noStroke();

  p5obj.fill(240, 255, 230, 90);
  p5obj.circle(p5obj.random(1000), p5obj.random(380, 800), p5obj.random(2, 36));

  if (iLevel>1)
  {
    star(iX, iY, iLevel-1);
  }
}

};

export default sketch;
