const sketch = (p:any) => {
    p.setup = () => {
p.createCanvas(500, 500);
p.background(280, 280, 280);

var a=25;
var b=12.5;

p.push();
p.translate(-a*2, -a*2);
for (var x=0; x<=600; x=x+a*4)
{
  for (var y=0; y<=600; y=y+a*4)
  {
    p.fill(p.random(10, 100), p.random(150, 200), y+200, a*2.5);
    p.strokeWeight(3);
    p.stroke(0, p.random(150, 200), y+200, a);
    //讓ｪ荳ｦ縺ｳ縺ｮ繝繧､繧｢・募・
    p.quad(x+0, y+0,
      x+35, y+50,
      x+ 0, y+100,
      -35+x, y+50);
  }
}
p.push();

for (var x=0; x<=500; x=x+100)
{
  for (var y=0; y<=500; y=y+100)
  {
    p.fill(280, 280, 280, 50);
    p.stroke(y+80, 200, x+250, a*3);
    //繧｢繧ｵ繧ｬ繧ｪ縺ｮ蜀・
    p.ellipse(x, y, 100, 100);
    p.ellipse(x+a*2, y+a*2, 100, 100);
  }
}

for (var x=0; x<=500; x=x+100)
{
  for (var y=0; y<=500; y=y+100)
  {

    p.fill(0, y+100, x+200, 120);
    p.strokeWeight(1);
    p.stroke(0, x+200, y+200, a*3);

    //螟門・縺ｮ蜊∝ｭ玲楔
    p.quad(x+0, y+0,
      x+15, y+a,
      x+ 0, y+a*2,
      -15+x, y+a);
    //12譎よ婿蜷・
    p.quad(x+0, y+a*2,
      x+15, y+a*3,
      x+ 0, y+100,
      -15+x, y+a*3);
    //6譎よ婿蜷・
    p.quad(x+0, y+50,
      x+a, y+35,
      x+a*2, y+a*2,
      25+x, y+65);
    //3譎よ婿蜷・
    p.quad(-a*2+x, y+a*2,
      -a+x, y+35,
      x, y+a*2,
      -a+x, y+65);
    //9譎よ婿蜷・

    //蜀・・縺ｮ蜊∝ｭ玲楔
    p.quad(x, y+12.5,
      x+7.5, y+a,
      x+ 0, y+a*2,
      -7.5+x, y+a);
    //12譎よ婿蜷・
    p.quad(x+0, y+a*2,
      x+7.5, y+a*3,
      x+ 0, y+b*7,
      -7.5+x, y+a*3);
    //6譎よ婿蜷・
    p.quad(x+0, y+50,
      x+a, y+b*3.4,
      x+a*1.5, y+a*2,
      25+x, y+b*4.6);
    //3譎よ婿蜷・
    p.quad(-b*3+x, y+a*2,
      -a+x, y+b*3.4,
      x, y+a*2,
      -a+x, y+b*4.6);
    //9譎よ婿蜷・
  }
}

  };
};

export default sketch;
